// Trevia Groteska font data for jsPDF (base64-encoded TTF)
const TREVIA_REGULAR_B64 = '';
const TREVIA_BOLD_B64 = '';

// Register Trevia Groteska in a jsPDF doc instance
function registerTreviaFont(doc) {
  doc.addFileToVFS('TreviaGroteska-Regular.ttf', TREVIA_REGULAR_B64);
  doc.addFont('TreviaGroteska-Regular.ttf', 'TreviaGroteska', 'normal');
  doc.addFileToVFS('TreviaGroteska-Bold.ttf', TREVIA_BOLD_B64);
  doc.addFont('TreviaGroteska-Bold.ttf', 'TreviaGroteska', 'bold');
}
